CREATE TABLE IF NOT EXISTS "expense_entries" ("description" TEXT NULL, "amount_centavos" TEXT NULL, "status" TEXT NOT NULL, "category_id" TEXT NULL, "subcategory_id" TEXT NULL, "recurrence_template_id" TEXT NULL, "scheduled_for_date" TEXT NULL, "scheduled_period_id" TEXT NULL, "id" TEXT NOT NULL, "owner_id" TEXT NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "accounting_period_id" TEXT NOT NULL, "competence_on" TEXT NOT NULL, "due_on" TEXT NULL, "paid_on" TEXT NULL, PRIMARY KEY ("owner_id", "id"), FOREIGN KEY (owner_id, accounting_period_id) REFERENCES accounting_periods (owner_id, id) ON DELETE RESTRICT, FOREIGN KEY (owner_id, recurrence_template_id) REFERENCES expense_recurrence_templates (owner_id, id) ON DELETE RESTRICT, FOREIGN KEY (owner_id, category_id) REFERENCES categories (owner_id, id) ON DELETE RESTRICT, FOREIGN KEY (owner_id, category_id, subcategory_id) REFERENCES subcategories (owner_id, category_id, id) ON DELETE RESTRICT, CHECK (
      amount_centavos IS NULL OR (
        length(amount_centavos) BETWEEN 1 AND 19
        AND amount_centavos NOT GLOB '*[^0-9]*'
        AND (amount_centavos = '0' OR
            substr(amount_centavos, 1, 1) BETWEEN '1' AND '9')
        AND (length(amount_centavos) < 19 OR
            amount_centavos <= '9223372036854775807')
      )
    ), CHECK (status IN ('pending', 'paid', 'cancelled')), CHECK (status <> 'paid' OR paid_on IS NOT NULL), CHECK (status <> 'pending' OR paid_on IS NULL), CHECK (amount_centavos IS NOT NULL OR recurrence_template_id IS NOT NULL), CHECK (subcategory_id IS NULL OR category_id IS NOT NULL));

CREATE TABLE IF NOT EXISTS "investment_allocations" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "created_at" TEXT NOT NULL, "updated_at" TEXT NOT NULL, "amount_centavos" TEXT NOT NULL, "allocated_on" TEXT NOT NULL, "accounting_period_id" TEXT NOT NULL, "cancelled_at" TEXT NULL, PRIMARY KEY ("owner_id", "id"), CHECK (
      amount_centavos IS NULL OR (
        length(amount_centavos) BETWEEN 1 AND 19
        AND amount_centavos NOT GLOB '*[^0-9]*'
        AND (amount_centavos = '0' OR
            substr(amount_centavos, 1, 1) BETWEEN '1' AND '9')
        AND (length(amount_centavos) < 19 OR
            amount_centavos <= '9223372036854775807')
      )
    ), FOREIGN KEY (owner_id, accounting_period_id) REFERENCES accounting_periods (owner_id, id) ON DELETE RESTRICT);
